  ('ai-assistant-usage', 'AI assistant usage', 'AI', 'Questions asked, answer ratings and usage by department. Shows totals only, never anyone''s conversations.', null, 'In development', 1),
  ('ai-literacy', 'AI literacy progress', 'AI', 'How many students and staff have completed the AI literacy modules, by department.', null, 'In development', 2),
  ('quantum-lab-jobs', 'Quantum Lab jobs', 'Quantum', 'Circuits run on simulators and real quantum hardware, queue times and hardware minutes used per course.', null, 'In development', 3),
