insert into public.departments (slug, name, short_name, kind, programmes, description, vision, mission, has_research_centre, research_areas, sort_order) values
  ('cse', 'Computer Science & Engineering', 'CSE', 'Engineering', 'BE', 'Software engineering, systems, data and AI, taught with industry tools and real projects.', 'To be a centre of excellence in computer science that produces engineers who build intelligent, secure and responsible software for society.', array['Teach strong foundations in computing through hands-on, AI-enabled learning.', 'Encourage research and innovation in AI, data science, cybersecurity and quantum computing.', 'Partner with industry for internships, projects and placements.', 'Develop ethical, lifelong learners who serve society.']::text[], true, array['Artificial intelligence and machine learning', 'Cybersecurity and post-quantum cryptography', 'Data science and cloud computing']::text[], 1),
  ('ise', 'Information Science & Engineering', 'ISE', 'Engineering', 'BE', 'Information systems, cloud computing, data engineering and web technologies.', 'To train skilled and ethical professionals with the ability to plan, design, develop, organize, and manage modern and traditional information systems — with comprehensive knowledge of Information Technologies, services, and global organizations.', array['To impart high-quality engineering education in the field of Information Science & Technology through strong theoretical foundations and extensive practical training methodologies, driven by innovation and research — to produce world-class engineers ready for global challenges.']::text[], false, '{}'::text[], 2),
  ('aiml', 'Artificial Intelligence & Machine Learning', 'AIML', 'Engineering', 'BE', 'Machine learning, deep learning, language models and responsible AI.', 'To be a leading department in artificial intelligence education, shaping engineers who build AI that is accurate, fair and useful.', array['Teach machine learning, deep learning and language models on strong mathematical foundations.', 'Give every student hands-on experience with real datasets and AI tools.', 'Collaborate with industry and research labs on applied AI projects.', 'Embed responsible AI, fairness and privacy in every course.']::text[], false, '{}'::text[], 3),
  ('me', 'Mechanical Engineering', 'ME', 'Engineering', 'BE', 'Design, manufacturing, thermal engineering and robotics.', 'To produce mechanical engineers who design, manufacture and maintain sustainable machines and systems.', array['Build strong fundamentals in design, thermal, manufacturing and materials engineering.', 'Integrate CAD, simulation, robotics and smart manufacturing into the curriculum.', 'Encourage research and prototyping through laboratories and the IDEA Lab.', 'Prepare graduates for industry, higher studies and entrepreneurship.']::text[], true, array['Thermal and energy systems', 'Advanced manufacturing and materials', 'Robotics and automation']::text[], 4),
  ('ece', 'Electronics & Communication Engineering', 'ECE', 'Engineering', 'BE', 'VLSI, embedded systems, signal processing and communication networks.', 'To be a centre of excellence in electronics and communication engineering that drives innovation in connected and intelligent systems.', array['Teach core electronics, communication and signal processing with hands-on laboratories.', 'Promote research in VLSI, embedded systems, IoT and wireless communication.', 'Strengthen industry collaboration for projects, training and placements.', 'Develop engineers with integrity and a commitment to society.']::text[], true, array['VLSI and embedded systems', 'Internet of Things and wireless communication', 'Signal and image processing']::text[], 5),
  ('mathematics', 'Mathematics', 'Maths', 'Basic sciences and humanities', 'Engineering mathematics for all programmes', 'Engineering mathematics, statistics and the foundations for AI and quantum computing.', 'To build the mathematical thinking every engineer needs to model, analyse and solve real problems.', array['Teach engineering mathematics with clarity and real-world applications.', 'Support AI, data science and quantum computing with strong foundations in linear algebra, probability and statistics.', 'Encourage research in pure and applied mathematics.', 'Mentor students who need additional support.']::text[], true, array['Applied and computational mathematics', 'Graph theory and optimisation', 'Statistics and data analysis']::text[], 6),
  ('physics', 'Physics', 'Physics', 'Basic sciences and humanities', 'Engineering physics for all programmes', 'Engineering physics, materials and the quantum mechanics behind quantum computing.', 'To inspire curiosity about the physical world and give engineers the scientific foundation for emerging technologies, including quantum.', array['Teach engineering physics through experiments and demonstrations.', 'Introduce quantum mechanics as the foundation for quantum computing and sensing.', 'Promote research in materials, photonics and applied physics.', 'Develop scientific temper and careful measurement habits.']::text[], true, array['Materials science and thin films', 'Photonics and optics', 'Quantum physics and sensing']::text[], 7),
  ('chemistry', 'Chemistry', 'Chemistry', 'Basic sciences and humanities', 'Engineering chemistry for all programmes', 'Engineering chemistry for materials, energy and the environment.', 'To give engineers a strong foundation in chemistry for sustainable materials, energy and the environment.', array['Teach engineering chemistry with a focus on materials, energy and the environment.', 'Train students in safe and accurate laboratory practice.', 'Promote research in green chemistry, corrosion and energy storage.', 'Raise awareness of sustainability and environmental responsibility.']::text[], true, array['Green chemistry and sustainable materials', 'Corrosion science and surface coatings', 'Electrochemistry and energy storage']::text[], 8),
  ('humanities', 'Humanities', 'Humanities', 'Basic sciences and humanities', 'Courses for all programmes', 'Communication, professional ethics, Universal Human Values and the Constitution of India.', 'To develop engineers who communicate clearly, think critically and act with integrity.', array['Build professional communication, writing and presentation skills.', 'Teach Universal Human Values, professional ethics and the Constitution of India.', 'Strengthen language, soft skills and career readiness.', 'Encourage social awareness and responsible citizenship.']::text[], false, '{}'::text[], 9),
  ('sports', 'Physical Education and Sports', 'Sports', 'Physical education', 'Activities for all students', 'Indoor and outdoor sports, fitness and inter-college competitions.', 'To promote fitness, teamwork and sporting excellence as part of every student''s education.', array['Provide coaching for indoor and outdoor sports.', 'Encourage participation in university, state and national competitions.', 'Promote health, fitness and wellbeing for students and staff.', 'Build leadership, discipline and team spirit through sport.']::text[], false, '{}'::text[], 10)
on conflict (slug) do update set name = excluded.name, short_name = excluded.short_name, kind = excluded.kind, programmes = excluded.programmes, description = excluded.description, vision = excluded.vision, mission = excluded.mission, has_research_centre = excluded.has_research_centre, research_areas = excluded.research_areas, sort_order = excluded.sort_order;
insert into public.houses (slug, name, namesake, about, motto, is_placeholder, sort_order) values
  ('abdul-kalam', 'Dr. A. P. J. Abdul Kalam House', 'Dr. A. P. J. Abdul Kalam (1931–2015) was an aerospace scientist who led India''s satellite launch vehicle and missile programmes, and served as the 11th President of India.', 'Abdul Kalam House celebrates curiosity, hard work and service through science. Members are encouraged to dream big and to turn ideas into things that help people.', null, false, 1),
  ('mother-teresa', 'Mother Teresa House', 'Mother Teresa (1910–1997) founded the Missionaries of Charity in Kolkata and spent her life caring for the poorest and sickest. She received the Nobel Peace Prize in 1979.', 'Mother Teresa House stands for compassion and service. Members lead community outreach and look out for one another on campus.', null, false, 2),
  ('rabindranath-tagore', 'Rabindranath Tagore House', 'Rabindranath Tagore (1861–1941) was a poet, writer, composer and educator who wrote India''s national anthem and won the Nobel Prize in Literature in 1913.', 'Tagore House celebrates creativity, culture and learning without limits. Members lead the arts, literature and music on campus.', null, false, 3),
  ('house-4', 'House 4', null, 'The name and namesake of this house will be announced soon.', null, true, 4),
  ('house-5', 'House 5', null, 'The name and namesake of this house will be announced soon.', null, true, 5)
on conflict (slug) do update set name = excluded.name, namesake = excluded.namesake, about = excluded.about, motto = excluded.motto, is_placeholder = excluded.is_placeholder, sort_order = excluded.sort_order;
insert into public.journey_milestones (slug, period, icon, title, summary, points, badge, photos, sort_order, layer, status, inline_photo) values
  ('jan-feb-2026', 'January – February 2026', 'sunrise', 'The Awakening — Principal''s Vision Sessions', 'Our transformation began with conviction from the top. The Principal conducted multiple intensive awareness sessions with all department heads and faculty members, laying the groundwork for a campus-wide AI revolution.', array['Principal-led awareness sessions with all HoDs and faculty across all departments', 'Introduction to AI terminologies: Machine Learning, Deep Learning, Generative AI, Agentic AI, Quantum Computing', 'Why AI matters for engineering colleges — impact on admissions, placements, and NAAC', 'Demystifying Quantum Computing — what it means for our students'' future', 'Building a shared vocabulary and urgency across the institution', 'Identifying AI champions in each department']::text[], null, '[]'::jsonb, 1, null, 'completed', null),
  ('mar-2026', 'March 2026', 'hammer', 'Building AI — From Theory to Working Portals', 'March saw HKBK move from awareness to action. Our AIML department built real, working AI applications — proving that AI is not just for tech giants. This hands-on approach earned us national recognition.', array['AI-powered presentation tools deployed for faculty use', 'UHV (Universal Human Values) Portal — first AI-integrated academic portal', 'Result Analysis System — automated student performance analysis using AI', 'Student IA Marks Chatbot — students can query their marks using natural language', 'Faculty Prompt Library — curated academic prompts for teaching, NAAC, research', 'HKBK EduStream — YouTube-style college video library with role-based access']::text[], 'AICTE Recognition: Potential Nodal Center for Universal Human Values', '[]'::jsonb, 2, null, 'completed', null),
  ('apr-2026', 'April 2026', 'presentation', '6-Month AI Transformation Program — Expert Partnership', 'HKBK partnered with industry expert **Mr. Rocky Jagtiani** to launch a comprehensive 6-month AI transformation program. Three intensive Faculty Development Programs were conducted, covering prompt engineering, hands-on AI tools, and pedagogical innovation.', array['**FDP Cohort 1** — Prompt Engineering Fundamentals: Persona–Context–Task–Output framework', '**FDP Cohort 2** — AI for Academic Work: Lesson plans, question papers, SSR writing, viva questions', '**FDP Cohort 3** — Hands-on AI Tools: Hugging Face, Google Colab, Python, APIs', '25–30 faculty teams formed; 25–30 real-world problems identified', '25–30 prompts built and tested on real documents → Prompt Library v1 created', 'Design Thinking workshop for faculty innovation']::text[], null, '[{"src":"/images/journey/fdp4.jpg","alt":"Mission AI-First @HKBK: poster for the 6-month programme and its April cohorts","fit":"contain"},{"src":"/images/journey/fdp1.jpg","alt":"Lighting the lamp at the programme inauguration","fit":"cover"},{"src":"/images/journey/fdp2.jpg","alt":"Guests and faculty at the programme inauguration","fit":"cover"},{"src":"/images/journey/fdp3.jpg","alt":"Presentation of a memento at the inauguration","fit":"cover"},{"src":"/images/journey/fdp5.jpg","alt":"Faculty taking part in an FDP session","fit":"cover"},{"src":"/images/journey/fdp9.jpg","alt":"Faculty working in teams during an FDP session","fit":"cover"},{"src":"/images/journey/fdp10.jpg","alt":"Faculty working on laptops during an FDP session","fit":"cover"},{"src":"/images/journey/fdp6.jpg","alt":"Hands-on guidance for a faculty member","fit":"cover"},{"src":"/images/journey/fdp7.jpg","alt":"Hands-on guidance during an FDP session","fit":"cover"},{"src":"/images/journey/fdp8.jpg","alt":"Faculty practising with AI tools","fit":"cover"},{"src":"/images/journey/fdp11.jpg","alt":"FDP session in the seminar hall","fit":"cover"},{"src":"/images/journey/fdp12.jpg","alt":"Panel and participants in the seminar hall","fit":"cover"}]'::jsonb, 3, null, 'completed', '{"src":"/images/journey/apr-2026-expert-partner.jpg","alt":"Portrait of a man in a blue checked shirt","caption":""}'::jsonb),
  ('may-2026', 'May 2026', 'sprout', 'Layer 1 Deployed — Awareness Campus Goes Live', 'May marks the full activation of Layer 1 of the 5-layer AI framework. AI is now being used across departments in teaching, planning, and administration. The transformation is happening at scale.', array['AI-assisted lesson planning deployed across Computer Science, IS, AIML, ECE, MBA', 'Automated assessments — AI-generated question papers and viva questions', 'AI literacy program for all students (2nd, 3rd, 4th year)', 'Multidisciplinary AI projects introduced for 2nd semester students (3 credits)', 'AI rubrics integrated into Civil, Mechanical, and Humanities assessments', 'Administrative workflow automation — SSR writing, evidence documentation']::text[], null, '[]'::jsonb, 4, null, 'in_progress', null),
  ('m-2026-06', 'June – July 2026', 'trophy', 'AI Faculty Champions Recognised — AI Transformation Workshop', 'HKBK College of Engineering, Bangalore, organised an AI Transformation Workshop for its faculty. Faculty members who showed outstanding participation and active contribution were recognised as AI Faculty Champions, honouring their enthusiasm and commitment to adopting AI-driven practices.', array['AI Transformation Workshop organised by HKBK College of Engineering, Bangalore', 'Faculty members recognised as "AI Faculty Champions" with a Certificate of Recognition', 'Recognition awarded for outstanding participation and active contribution throughout the workshop', 'Celebrates faculty enthusiasm and commitment to adopting AI-driven practices in teaching and academic work', 'Certificates jointly issued by the industry training partner and the leadership of HKBK Group of Institutions', 'AI Faculty Champions now lead AI adoption in their departments, mentoring colleagues and guiding responsible AI use']::text[], null, '[]'::jsonb, 5, 2, 'completed', null),
  ('m-2026-07', 'July 2026', 'sparkles', '', null, '{}'::text[], null, '[]'::jsonb, 6, null, 'completed', null),
  ('m-2026-08', 'August – September 2026', 'rocket', 'AI in Action — Industry Consultancy: AI Customer-Support Chatbot', 'The AI First initiative moved from the classroom to real-world delivery with an industry consultancy project: an AI-powered customer-support chatbot and Instagram operations system for Camellia Artisanal, a food business. The system answers customer questions using approved business knowledge and hands over to a human whenever a question needs one.', array['AI chatbot built on structured intent understanding with a controlled RAG/LLM layer, designed never to invent prices, stock, shelf life or delivery promises', 'Canonical business-knowledge catalogue so every answer comes from one approved source', 'Instagram integration: replies that recognise which post, reel or Story the customer is responding to, with Story auto-sync', 'Safe human handoff with owner notifications (admin panel, email and web push)', 'Privacy safeguards: hashed customer identifiers in logs, with no raw IDs or customer messages stored', 'Over 2,400 automated tests passing, with staged releases and live acceptance testing before every production update']::text[], null, '[]'::jsonb, 7, 2, 'completed', null),
  ('m-2026-09', 'September 2026', 'sparkles', '', null, '{}'::text[], null, '[]'::jsonb, 8, null, 'completed', null),
  ('m-2026-10', 'September – October 2026', 'cpu', 'Smart Campus Operations — Digital Systems on the Zoho Platform', 'September and October took the AI First journey into campus operations. Using the Zoho Creator low-code platform, HKBK began building its own digital systems for Hostel Management and Attendance Management, replacing manual registers and spreadsheets with secure, role-based apps and live dashboards. Alongside this, a new Alumni Portal is being developed as part of the HKBK college website. The systems are being built in-house by HKBK students under faculty mentorship.', array['Hostel Management System for the Boys and Girls hostels: one central app with role-based access for the Principal, Super Admin, Wardens, Operations and Students', 'Live hostel dashboards with student search, fee tracking, attendance calendar, memos and quick actions', 'Automated account approvals, maintenance and service tickets raised by students and handled by the Operations team, with urgent-ticket flagging by the Principal', 'Branded printable reports with one-click PDF and CSV download, carrying the HKBK logo, college name and timestamps', 'Attendance Management system to record and track attendance digitally, with summaries for faculty and administrators', 'Secure by design: each user sees only the data their role allows', 'Alumni Portal on the HKBK college website to build the alumni network: alumni registration, profiles and a channel to stay connected with the college']::text[], null, '[]'::jsonb, 9, 4, 'in_progress', null),
  ('m-2026-11', 'November 2026', 'sparkles', '', null, '{}'::text[], null, '[]'::jsonb, 10, null, 'upcoming', null),
  ('m-2026-12', 'December 2026', 'sparkles', '', null, '{}'::text[], null, '[]'::jsonb, 11, null, 'upcoming', null)
on conflict (slug) do nothing;
