insert into public.training_programs (slug, title, track, duration, mode, audience, summary, is_sample, sort_order) values
  ('genai-professionals', 'Generative AI for working professionals', 'Artificial intelligence', '3 days', 'Campus, office or online', 'Managers and engineers', 'Use language models safely at work: prompting, retrieval, evaluation and data privacy.', true, 1),
  ('applied-ml-python', 'Applied machine learning with Python', 'Artificial intelligence', '5 days', 'Campus, office or online', 'Developers and analysts', 'Build, evaluate and deploy machine learning models on your own data.', true, 2),
  ('quantum-foundations', 'Quantum computing foundations with Qiskit', 'Quantum computing', '3 days', 'Campus or online', 'Engineers and researchers', 'Qubits, gates and circuits, with hands-on runs on simulators and real quantum hardware.', true, 3),
  ('pqc-security-teams', 'Post-quantum cryptography for security teams', 'Quantum computing', '2 days', 'Campus, office or online', 'Security and IT teams', 'The new NIST standards, building a cryptographic inventory, and planning a migration.', true, 4),
  ('fullstack-nextjs-supabase', 'Full-stack web with Next.js and Supabase', 'Software engineering', '5 days', 'Campus or online', 'Developers', 'Build secure web applications with React Server Components, Postgres and row-level security.', true, 5),
  ('embedded-iot', 'Embedded systems and IoT', 'Core engineering', '4 days', 'Campus', 'Engineers and technicians', 'Microcontrollers, sensors and connected devices, from prototype to deployment.', true, 6),
  ('cad-simulation', 'CAD and simulation for mechanical design', 'Core engineering', '3 days', 'Campus', 'Design and production engineers', 'Model parts, run stress and thermal simulations, and prepare designs for manufacture.', true, 7),
  ('values-for-leaders', 'Human values for team leaders', 'Leadership', '1 day', 'Campus or office', 'Team leads and managers', 'A UHV-based workshop on trust, respect and decision-making in teams.', true, 8)
